/* ============================================================
   CORRI MARI! - mini-gioco platform per il sito del matrimonio
   Uso:  <div id="corri-mari"></div>
         <script src="corri-mari.js"><\/script>
   Oppure:  CorriMari.mount('#un-altro-div');
   Tutto incluso (sprite in base64), nessuna dipendenza.
   ============================================================ */
(function(){
  'use strict';

  const BRIDE_SRC = "data:image/png;base64,";
  const GROOM_SRC = "data:image/png;base64,";
  const FW = 120, FH = 200;    // frame sposa (4: idle, corsa1, corsa2, salto)
  const GFW = 120, GFH = 200;  // frame sposo (2: fermo, braccia aperte)

  // ---- classifica -----------------------------------------------------
  // Endpoint dell'API su Vercel. Cambia qui se lo monti su un path diverso.
  const API = (window.CORRI_MARI_API || '/api/score');
  const TIMER_START = 100;

  async function inviaPunteggio(nome, secondi, cuori){
    const r = await fetch(API, {
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body: JSON.stringify({nome, secondi, cuori})
    });
    if(!r.ok) throw new Error('HTTP '+r.status);
    return r.json();
  }
  async function leggiClassifica(){
    const r = await fetch(API, {cache:'no-store'});
    if(!r.ok) throw new Error('HTTP '+r.status);
    return r.json();
  }
  function esc(t){
    return String(t).replace(/[&<>"']/g, c =>
      ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }
  function tabella(righe, evidenzia){
    if(!righe || !righe.length) return '<p>Nessun punteggio ancora. Sii il primo!</p>';
    let h = '<table class="cm-tab"><tr><th>#</th><th>Nome</th><th>Tempo</th><th>&#10084;</th></tr>';
    righe.slice(0,10).forEach((r,i)=>{
      const me = (evidenzia && r.nome===evidenzia.nome && r.secondi===evidenzia.secondi);
      h += '<tr class="'+(me?'cm-me':'')+'"><td>'+(i+1)+'</td><td>'+esc(r.nome)+
           '</td><td>'+r.secondi.toFixed(1)+'s</td><td>'+r.cuori+'</td></tr>';
    });
    return h + '</table>';
  }

  const CSS = `
  .cm-box{font-family:'Trebuchet MS',sans-serif;display:flex;flex-direction:column;
    align-items:center;gap:10px;max-width:820px;margin:0 auto;color:#fff}
  .cm-title{font-size:20px;letter-spacing:2px;color:#e8c98a;text-shadow:2px 2px 0 #8c3d22;margin:0}
  .cm-wrap{position:relative;width:100%;box-shadow:0 12px 40px rgba(0,0,0,.35);
    border:4px solid #e8c98a;border-radius:6px;overflow:hidden;background:#a9c2b6}
  .cm-cv{display:block;width:100%;height:auto}
  .cm-hud{position:absolute;top:8px;left:10px;font-size:13px;font-weight:bold;
    text-shadow:2px 2px 0 #000;pointer-events:none;color:#fff}
  .cm-msg{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;
    justify-content:center;background:rgba(70,20,19,.88);text-align:center;gap:12px;padding:20px}
  .cm-msg h2{font-size:26px;color:#e8c98a;text-shadow:2px 2px 0 #8c3d22;margin:0}
  .cm-msg p{font-size:14px;max-width:420px;line-height:1.5;opacity:.9;margin:0}
  .cm-msg button,.cm-go{background:#b85c38;border:none;color:#fff;padding:10px 24px;font-size:15px;
    font-weight:bold;border-radius:20px;cursor:pointer;box-shadow:0 4px 0 #8c3d22}
  .cm-msg button:active{transform:translateY(3px);box-shadow:0 1px 0 #8c3d22}
  .cm-hide{display:none!important}
  .cm-nome{padding:9px 12px;font-size:15px;border-radius:16px;border:2px solid #e8c98a;
    background:#f9f4ed;color:#2c2419;text-align:center;width:220px;max-width:80%;outline:none}
  .cm-row{display:flex;gap:8px;align-items:center;flex-wrap:wrap;justify-content:center}
  .cm-alt{background:#4e5f44;border:2px solid #e8c98a;box-shadow:none}
  .cm-stato{min-height:16px;font-size:12px;opacity:.85}
  .cm-tab{border-collapse:collapse;font-size:13px;background:rgba(255,255,255,.06);
    border-radius:8px;overflow:hidden}
  .cm-tab th,.cm-tab td{padding:5px 12px;text-align:center}
  .cm-tab th{background:#b85c38;font-size:12px}
  .cm-tab tr:nth-child(even) td{background:rgba(255,255,255,.05)}
  .cm-me td{background:#e8c98a!important;color:#8c3d22;font-weight:bold}
  .cm-ctrl{display:flex;gap:10px}
  .cm-pad{width:64px;height:56px;background:#4e5f44;border:2px solid #e8c98a;border-radius:10px;
    display:flex;align-items:center;justify-content:center;font-size:22px;color:#fff;
    user-select:none;-webkit-user-select:none;touch-action:none;cursor:pointer}
  .cm-pad:active{background:#b85c38}
  .cm-J{width:110px;font-size:14px;font-weight:bold}
  `;

  const HTML = `
  <h3 class="cm-title">&#128141; CORRI MARI &#128141;</h3>
  <div class="cm-wrap">
    <canvas class="cm-cv" width="800" height="400"></canvas>
    <div class="cm-hud"></div>
    <div class="cm-msg">
      <h2>Raggiungi lo Sposo!</h2>
      <p>Salta le piattaforme, schiva i cuori spezzati e corri tra le braccia di Stefano.
         <br>Frecce / A-D per muoverti &middot; Spazio o Su per saltare.</p>
      <button class="cm-go">GIOCA</button>
    </div>
  </div>
  <div class="cm-ctrl">
    <div class="cm-pad cm-L">&#9664;</div>
    <div class="cm-pad cm-R">&#9654;</div>
    <div class="cm-pad cm-J">SALTA</div>
  </div>`;

  function boot(root){
    if(root.dataset.cmReady) return;
    root.dataset.cmReady = '1';
    if(!document.getElementById('cm-style')){
      const st = document.createElement('style');
      st.id = 'cm-style'; st.textContent = CSS;
      document.head.appendChild(st);
    }
    root.classList.add('cm-box');
    root.innerHTML = HTML;

    const bride = new Image(); bride.src = BRIDE_SRC;
    const groom = new Image(); groom.src = GROOM_SRC;

  const cv = root.querySelector('.cm-cv'), ctx = cv.getContext('2d');
  const W = 800, H = 400, G = 0.62, LEVEL_END = 4600;
  const hud = root.querySelector('.cm-hud'), msg = root.querySelector('.cm-msg');
    let goBtn = root.querySelector('.cm-go');

  const keys = {};
  window.addEventListener('keydown', e => { keys[e.code] = true; if(['Space','ArrowUp','ArrowLeft','ArrowRight','ArrowDown'].includes(e.code)) e.preventDefault(); });
  window.addEventListener('keyup',   e => { keys[e.code] = false; });
  function bindPad(id, code){ const el = root.querySelector('.cm-'+id);
    const on = e => { e.preventDefault(); keys[code] = true; }, off = e => { e.preventDefault(); keys[code] = false; };
    el.addEventListener('touchstart', on, {passive:false}); el.addEventListener('touchend', off, {passive:false});
    el.addEventListener('mousedown', on); el.addEventListener('mouseup', off); el.addEventListener('mouseleave', off);
  }
  bindPad('L','ArrowLeft'); bindPad('R','ArrowRight'); bindPad('J','Space');

  // --- level layout ---
  const PLAT = [
    {x:0,y:352,w:900,h:48},
    {x:980,y:352,w:520,h:48},
    {x:1180,y:262,w:120,h:20},
    {x:1400,y:210,w:120,h:20},
    {x:1580,y:352,w:420,h:48},
    {x:1680,y:250,w:110,h:20},
    {x:2080,y:352,w:300,h:48},
    {x:2100,y:240,w:130,h:20},
    {x:2320,y:180,w:130,h:20},
    {x:2460,y:352,w:560,h:48},
    {x:2600,y:255,w:120,h:20},
    {x:2820,y:200,w:120,h:20},
    {x:3100,y:352,w:340,h:48},
    {x:3180,y:245,w:140,h:20},
    {x:3420,y:190,w:130,h:20},
    {x:3520,y:352,w:600,h:48},
    {x:3700,y:255,w:120,h:20},
    {x:3900,y:205,w:120,h:20},
    {x:4200,y:352,w:700,h:48}
  ];
  const COINS = [
    {x:600,y:300},{x:700,y:300},{x:1220,y:215},{x:1440,y:165},{x:1720,y:205},
    {x:2140,y:195},{x:2360,y:135},{x:2640,y:210},{x:2860,y:155},{x:3220,y:200},
    {x:3460,y:145},{x:3740,y:210},{x:3940,y:160},{x:4350,y:300},{x:4450,y:300}
  ];
  const ENEM = [
    {x:1050,y:320,min:1000,max:1440,d:1},
    {x:1750,y:320,min:1600,max:1960,d:-1},
    {x:2550,y:320,min:2480,max:2980,d:1},
    {x:3200,y:320,min:3110,max:3400,d:-1},
    {x:3700,y:320,min:3540,max:4080,d:1},
    {x:2900,y:320,min:2480,max:2980,d:-1}
  ];
  const GAPS = [[900,980],[1500,1580],[2000,2080],[2380,2460],[3020,3100],[3440,3520],[4120,4200]];

  let p, coins, enem, cam, state, kisses, timeLeft, last;

  function reset(){
    p = {x:60,y:250,w:34,h:58,vx:0,vy:0,onG:false,face:1,inv:0,bob:0,anim:0};
    coins = COINS.map(c => ({...c, got:false, t:Math.random()*6}));
    enem  = ENEM.map(e => ({...e, alive:true, w:30, h:30}));
    cam = 0; kisses = 3; timeLeft = 100; state = 'play'; last = performance.now();
  }

  function hit(a,b){ return a.x < b.x+b.w && a.x+a.w > b.x && a.y < b.y+b.h && a.y+a.h > b.y; }

  function update(dt){
    timeLeft -= dt/1000;
    if(timeLeft <= 0){ state = 'lose'; show('Tempo scaduto!','Stefano ti aspetta ancora... riprova!'); return; }

    const L = keys['ArrowLeft']||keys['KeyA'], R = keys['ArrowRight']||keys['KeyD'];
    const J = keys['Space']||keys['ArrowUp']||keys['KeyW'];

    if(L){ p.vx -= 0.7; p.face = -1; }
    if(R){ p.vx += 0.7; p.face = 1; }
    p.vx *= 0.84;
    p.vx = Math.max(-6.5, Math.min(6.5, p.vx));
    if(J && p.onG){ p.vy = -12.6; p.onG = false; }
    if(!J && p.vy < -4) p.vy += 0.45;   // variable jump height

    p.vy += G;
    if(p.vy > 16) p.vy = 16;

    p.x += p.vx;
    if(p.x < 0) { p.x = 0; p.vx = 0; }
    for(const s of PLAT){
      if(hit(p,s)){
        if(p.vx > 0) p.x = s.x - p.w;
        else if(p.vx < 0) p.x = s.x + s.w;
        p.vx = 0;
      }
    }

    p.y += p.vy; p.onG = false;
    for(const s of PLAT){
      if(hit(p,s)){
        if(p.vy > 0){ p.y = s.y - p.h; p.vy = 0; p.onG = true; }
        else if(p.vy < 0){ p.y = s.y + s.h; p.vy = 1; }
      }
    }

    if(p.onG && Math.abs(p.vx) > 0.6) p.bob += 0.25; else p.bob = 0;
    if(p.inv > 0) p.inv -= dt;

    if(p.y > H + 60){ damage(true); }

    for(const e of enem){
      if(!e.alive) continue;
      e.x += e.d * 1.35;
      if(e.x < e.min || e.x > e.max) e.d *= -1;
      if(hit(p,e)){
        if(p.vy > 1.5 && p.y + p.h - p.vy < e.y + 12){ e.alive = false; p.vy = -8; }
        else damage(false);
      }
    }

    for(const c of coins){
      c.t += dt/120;
      if(!c.got && Math.hypot(p.x+19-c.x, p.y+19-c.y) < 30) c.got = true;
    }

    if(p.x > LEVEL_END - 70){
      state = 'win';
      const got = coins.filter(c=>c.got).length;
      const impiegato = Math.max(0.1, TIMER_START - timeLeft);   // tempo IMPIEGATO
      chiediNome(impiegato, got, coins.length);
    }

    const target = p.x - W*0.35;
    cam += (Math.max(0, Math.min(LEVEL_END - W + 120, target)) - cam) * 0.1;
  }

  function damage(fell){
    if(p.inv > 0 && !fell) return;
    kisses--;
    if(kisses <= 0){ state='lose'; show('Ahi!','I cuori spezzati ti hanno fermata.<br>Ma l\'amore riprova sempre!'); return; }
    p.inv = 1400;
    if(fell){ p.x = Math.max(40, p.x - 160); p.y = 240; p.vy = 0; p.vx = 0; }
    else { p.vy = -7; p.vx = -p.face * 5; }
  }

  function chiediNome(secondi, cuori, totCuori){
    msg.classList.remove('cm-hide');
    msg.innerHTML =
      '<h2>&#128139; L\'hai raggiunto!</h2>'+
      '<p>Mari corre tra le braccia di Stefano.<br>'+
      'Tempo: <b>'+secondi.toFixed(1)+'s</b> &middot; Cuori: <b>'+cuori+'/'+totCuori+'</b></p>'+
      '<input class="cm-nome" maxlength="24" placeholder="Il tuo nome" autocomplete="off">'+
      '<div class="cm-row">'+
        '<button class="cm-salva">SALVA</button>'+
        '<button class="cm-skip cm-alt">Salta</button>'+
      '</div>'+
      '<p class="cm-stato"></p>';

    const inp   = msg.querySelector('.cm-nome');
    const stato = msg.querySelector('.cm-stato');
    const btn   = msg.querySelector('.cm-salva');
    inp.focus();

    // ricorda il nome tra una partita e l'altra (comodo su mobile)
    try { inp.value = sessionStorage.getItem('cm_nome') || ''; } catch(e){}

    async function salva(){
      const nome = inp.value.trim();
      if(!nome){ stato.textContent = 'Scrivi il tuo nome.'; inp.focus(); return; }
      btn.disabled = true; stato.textContent = 'Salvataggio...';
      try { sessionStorage.setItem('cm_nome', nome); } catch(e){}
      try{
        const r = await inviaPunteggio(nome, secondi, cuori);
        if(!r.ok) throw new Error(r.errore || 'errore');
        mostraClassifica(r.classifica, {nome, secondi:Math.round(secondi*10)/10}, r.posizione);
      }catch(e){
        btn.disabled = false;
        stato.textContent = 'Non riesco a salvare. Riprova.';
      }
    }
    btn.onclick = salva;
    inp.onkeydown = e => { if(e.key === 'Enter') salva(); };
    msg.querySelector('.cm-skip').onclick = () => mostraClassifica(null, null, 0);
  }

  async function mostraClassifica(righe, mio, posizione){
    msg.classList.remove('cm-hide');
    if(!righe){
      msg.innerHTML = '<h2>Classifica</h2><p>Carico...</p>';
      try{ const r = await leggiClassifica(); righe = r.classifica; }
      catch(e){
        msg.innerHTML = '<h2>Classifica</h2><p>Non disponibile al momento.</p>'+
                        '<button class="cm-go">RIGIOCA</button>';
        msg.querySelector('.cm-go').onclick = start; return;
      }
    }
    msg.innerHTML =
      '<h2>&#127942; Classifica</h2>'+
      (posizione ? '<p>Sei <b>'+posizione+'&deg;</b>!</p>' : '')+
      tabella(righe, mio)+
      '<button class="cm-go">RIGIOCA</button>';
    msg.querySelector('.cm-go').onclick = start;
  }

  function show(t, s){
    msg.classList.remove('cm-hide');
    msg.innerHTML = '<h2>'+t+'</h2><p>'+s+'</p>'+
      '<div class="cm-row"><button class="cm-go">RIGIOCA</button>'+
      '<button class="cm-cls cm-alt">Classifica</button></div>';
    root.querySelector('.cm-go').onclick = start;
    root.querySelector('.cm-cls').onclick = () => mostraClassifica(null, null, 0);
  }

  // --- drawing ---
  function cloud(x,y,s){
    ctx.fillStyle='rgba(249,244,237,.85)';
    ctx.beginPath();
    ctx.arc(x,y,18*s,0,7); ctx.arc(x+22*s,y-8*s,22*s,0,7); ctx.arc(x+46*s,y,17*s,0,7);
    ctx.fill();
  }
  function heart(x,y,s,col){
    ctx.fillStyle=col; ctx.beginPath();
    ctx.moveTo(x, y+s*0.75);
    ctx.bezierCurveTo(x-s, y-s*0.15, x-s*0.5, y-s, x, y-s*0.35);
    ctx.bezierCurveTo(x+s*0.5, y-s, x+s, y-s*0.15, x, y+s*0.75);
    ctx.fill();
  }

  function drawGroom(gx, gy){
      const GROUND_Y = 352;   // superficie della piattaforma finale
    const near = Math.abs(p.x - gx) < 220 || state === 'win';
      const f = near ? 1 : 0;
      const DW = 60, DH = Math.round(60 * GFH / GFW);
      if(groom.complete && groom.naturalWidth)
        ctx.drawImage(groom, f*GFW, 0, GFW, GFH, gx - DW/2, GROUND_Y - DH + 2, DW, DH);
    }

  function draw(){
    // sky
    const g = ctx.createLinearGradient(0,0,0,H);
    g.addColorStop(0,'#a9c2b6'); g.addColorStop(1,'#f5efe6');
    ctx.fillStyle=g; ctx.fillRect(0,0,W,H);

    for(let i=0;i<9;i++){
      const cx = ((i*430 - cam*0.25) % (W+300)) - 150;
      cloud(cx, 50 + (i%3)*42, 0.7 + (i%2)*0.35);
    }
    // hills
    ctx.fillStyle='#7a8c6e';
    for(let i=0;i<8;i++){
      const hx = ((i*380 - cam*0.5) % (W+400)) - 200;
      ctx.beginPath(); ctx.arc(hx, 380, 110, Math.PI, 0); ctx.fill();
    }

    ctx.save(); ctx.translate(-cam, 0);

    // platforms
    for(const s of PLAT){
      if(s.x - cam > W+50 || s.x + s.w - cam < -50) continue;
      if(s.h > 30){
        ctx.fillStyle='#7a8c6e'; ctx.fillRect(s.x, s.y, s.w, 12);
        ctx.fillStyle='#c97c52'; ctx.fillRect(s.x, s.y+12, s.w, s.h-12);
        ctx.fillStyle='#8c3d22';
        for(let bx=s.x; bx<s.x+s.w; bx+=32) ctx.fillRect(bx+2, s.y+18, 26, 10);
      } else {
        ctx.fillStyle='#e8c98a'; ctx.fillRect(s.x, s.y, s.w, s.h);
        ctx.fillStyle='#f9f4ed'; ctx.fillRect(s.x, s.y, s.w, 5);
        ctx.strokeStyle='#8c3d22'; ctx.lineWidth=2; ctx.strokeRect(s.x, s.y, s.w, s.h);
      }
    }

    // coins = hearts
    for(const c of coins){
      if(c.got) continue;
      heart(c.x, c.y + Math.sin(c.t)*4, 12, '#c8a460');
      heart(c.x-3, c.y - 3 + Math.sin(c.t)*4, 4, 'rgba(249,244,237,.7)');
    }

    // enemies = broken hearts
    for(const e of enem){
      if(!e.alive) continue;
      heart(e.x+15, e.y+8, 15, '#9a8c82');
      ctx.strokeStyle='#2c2419'; ctx.lineWidth=3;
      ctx.beginPath(); ctx.moveTo(e.x+15, e.y-6); ctx.lineTo(e.x+11, e.y+6);
      ctx.lineTo(e.x+19, e.y+12); ctx.lineTo(e.x+14, e.y+22); ctx.stroke();
    }

    // goal: altar + groom
    const gx = LEVEL_END, gy = 250;
    ctx.fillStyle='#f9f4ed'; ctx.fillRect(gx-70, 200, 140, 6);
    ctx.fillStyle='#c8a460'; ctx.fillRect(gx-66, 206, 8, 146); ctx.fillRect(gx+58, 206, 8, 146);
    for(let i=-3;i<=3;i++) heart(gx + i*20, 196, 9, i%2 ? '#b85c38' : '#e8c98a');
    drawGroom(gx, gy);
    ctx.fillStyle='#8c3d22'; ctx.font='bold 14px Trebuchet MS'; ctx.textAlign='center';
    ctx.fillText('STEFANO', gx, 190);
    ctx.textAlign='left';

    // bride sprite (sheet: 0 idle, 1-2 run, 3 jump)
    let fr = 0;
    if(!p.onG) fr = 3;
    else if(Math.abs(p.vx) > 0.6){ p.anim += Math.abs(p.vx)*0.035; fr = 1 + (Math.floor(p.anim) % 2); }
    else p.anim = 0;

    ctx.save();
    if(p.inv > 0 && Math.floor(p.inv/90)%2) ctx.globalAlpha = 0.35;
    const DW = 52, DH = Math.round(52 * FH / FW);   // drawn size, keeps aspect
    ctx.translate(p.x + p.w/2, p.y + p.h);          // anchor at feet
    ctx.scale(p.face, 1);
    if(bride.complete && bride.naturalWidth){
      ctx.drawImage(bride, fr*FW, 0, FW, FH, -DW/2, -DH + 4, DW, DH);
    } else {
      ctx.fillStyle='#fff'; ctx.fillRect(-16, -50, 32, 50);
    }
    ctx.restore();

    ctx.restore();

    const got = coins.filter(c=>c.got).length;
    let h = '';
    for(let i=0;i<kisses;i++) h += '&#128139;';
    hud.innerHTML = h + ' &nbsp;&#10084;&#65039; '+got+'/'+coins.length+
                    ' &nbsp;&#9203; '+Math.ceil(Math.max(0,timeLeft))+
                    ' &nbsp;&#128142; '+Math.max(0, Math.round((LEVEL_END - p.x)/10))+'m';
  }

  function loop(now){
    const dt = Math.min(34, now - last); last = now;
    if(state === 'play'){ update(dt); draw(); }
    requestAnimationFrame(loop);
  }

  function start(){ msg.classList.add('cm-hide'); reset(); }
  goBtn.onclick = start;
  reset(); draw();
  requestAnimationFrame(loop);

  }

  const CorriMari = {
    mount(sel){
      const el = typeof sel === 'string' ? document.querySelector(sel) : sel;
      if(el) boot(el);
      return el;
    }
  };
  window.CorriMari = CorriMari;

  function auto(){
    document.querySelectorAll('#corri-mari, .corri-mari, [data-corri-mari]').forEach(boot);
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', auto);
  else auto();
})();
